import type { PropertyRecord } from "./types";

/** Supabase stores the complete catalogue. Empty must never resurrect samples. */
export function catalogueRecords(saved: PropertyRecord[] | null, fallback: PropertyRecord[]): PropertyRecord[] {
  return (saved ?? fallback).map((record) => ({
    ...record,
    id: record.id || `cms-${record.slug}`,
    imageKey: record.imageKey ?? "",
    imageAlt: record.imageAlt ?? "",
  }));
}

/** Also used by 404.html on static hosts for newly published property URLs. */
export function propertySlug(pathname: string): string | null {
  const match = /^\/properties\/([^/]+)\/?$/.exec(pathname);
  if (!match) return null;
  try { return decodeURIComponent(match[1]); } catch { return null; }
}
