// CMS documents in Supabase.
//
// One table, `cms_documents`, keyed by the same path the rest of this project
// already uses:
//
//   applications/applications.json   the application forms
//   properties/properties.json       every property
//
// That is not a coincidence. MTC-KRP-031 defined the backend contract as
// `POST /api/save-json { path, content }`, and this is that contract with a
// Postgres row where the worker would have been. The path allow-list, the
// document shapes and the guarantees the browser makes before sending are all
// unchanged — which is why moving to Supabase is an adapter, not a rewrite.
//
// Reads are public. A property page has to render for somebody who is not
// signed in, so the row is readable by anyone and Row Level Security allows
// only authenticated users to write. See supabase/schema.sql.

import { ALLOWED_PATHS } from "../../contracts/saveJson.ts";
import { supabaseRequest } from "./client.ts";
import type { SupabaseResult } from "./client";

const TABLE = "/rest/v1/cms_documents";

/**
 * A document together with the version it was read at.
 *
 * `updatedAt` is the database's own column, maintained by a trigger, so it
 * changes on every write by anybody. That makes it a usable version marker:
 * writing "only if updated_at is still what I read" is how one person saving
 * stops silently erasing another's work.
 *
 * Null means the row does not exist yet - which is itself a precondition
 * worth enforcing, since two browsers can both believe they are creating it.
 */
export type VersionedDocument<T> = {
  content: T | null;
  updatedAt: string | null;
};

export type CmsDocumentRow<T> = {
  path: string;
  content: T;
  updated_at?: string;
};

/**
 * Refuses a path the contract does not allow.
 *
 * The database enforces this too, with a CHECK constraint. This copy exists so
 * a mistake fails here with a sentence somebody can read, rather than as a
 * Postgres constraint violation — it is a convenience, NOT the security
 * boundary. The boundary is in the schema.
 */
function allowed(path: string): boolean {
  return (ALLOWED_PATHS as readonly string[]).includes(path);
}

/**
 * Reads one document.
 *
 * A missing row is `null`, not an error, and that distinction matters: before
 * the first save there IS no row, and the CMS is supposed to fall back to its
 * bundled starting point rather than show a failure.
 */
export async function loadDocument<T>(
  path: string
): Promise<SupabaseResult<T | null>> {
  const query = `${TABLE}?path=eq.${encodeURIComponent(path)}&select=content`;

  const result = await supabaseRequest<CmsDocumentRow<T>[]>(query, {
    method: "GET",
    /* Public. The website itself reads properties, and it has no session. */
    authenticated: false,
  });

  if (!result.ok) return result;

  const row = Array.isArray(result.data) ? result.data[0] : null;
  return { ok: true, data: row ? row.content : null };
}

/**
 * Reads a document and the version it was at.
 *
 * Same request as `loadDocument`, one more column. Kept separate so the
 * callers that genuinely do not care - the public website rendering a
 * property page - are not handed a version they have no use for.
 */
export async function loadVersionedDocument<T>(
  path: string
): Promise<SupabaseResult<VersionedDocument<T>>> {
  const query =
    `${TABLE}?path=eq.${encodeURIComponent(path)}&select=content,updated_at`;

  const result = await supabaseRequest<
    { content: T; updated_at: string }[]
  >(query, { method: "GET", authenticated: false });

  if (!result.ok) return result;

  const row = Array.isArray(result.data) ? result.data[0] : null;

  return {
    ok: true,
    data: {
      content: row ? row.content : null,
      updatedAt: row ? row.updated_at : null,
    },
  };
}

/**
 * Writes a document only if nobody else has written it since it was read.
 *
 * `applied: false` is NOT an error - it means somebody got there first, and
 * the caller should re-read, re-apply its change to the newer version, and
 * try again. Reporting it as a failure would be wrong, and overwriting
 * regardless is what this exists to prevent.
 *
 * The condition is enforced by the database, in the WHERE clause of the
 * update, not by comparing in the browser - checking here and writing after
 * would leave exactly the gap it is meant to close.
 */
export async function saveDocumentIfUnchanged<T>(
  path: string,
  content: T,
  expectedUpdatedAt: string | null
): Promise<SupabaseResult<{ applied: boolean }>> {
  if (!allowed(path)) {
    return {
      ok: false,
      error: {
        status: 400,
        message: "That is not somewhere this site is allowed to save.",
      },
    };
  }

  /* No version means the row did not exist when it was read. A plain insert
     is the right thing: if another browser created it meanwhile, the primary
     key rejects this and the caller retries against their version rather than
     flattening it. */
  if (expectedUpdatedAt === null) {
    const created = await supabaseRequest<unknown[]>(TABLE, {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body: [{ path, content }],
    });

    if (!created.ok) {
      /* 409 is the duplicate key: somebody created it first. A conflict, not
         a failure - the caller re-reads and tries again. */
      if (created.error.status === 409) return { ok: true, data: { applied: false } };
      return created;
    }

    return { ok: true, data: { applied: true } };
  }

  const query =
    `${TABLE}?path=eq.${encodeURIComponent(path)}` +
    `&updated_at=eq.${encodeURIComponent(expectedUpdatedAt)}`;

  /* return=representation so the reply says which rows matched. Without it a
     write that changed nothing is indistinguishable from one that worked. */
  const result = await supabaseRequest<unknown[]>(query, {
    method: "PATCH",
    headers: { Prefer: "return=representation" },
    body: { content },
  });

  if (!result.ok) return result;

  const rows = Array.isArray(result.data) ? result.data.length : 0;
  return { ok: true, data: { applied: rows > 0 } };
}

/**
 * Writes one document, creating it if it does not exist.
 *
 * `Prefer: resolution=merge-duplicates` makes this an upsert on the primary
 * key, so the first save and the hundredth take the same path - no "does it
 * exist yet" branch to get wrong.
 *
 * UNCONDITIONAL: it overwrites whatever is there. Correct for the Application
 * Builder, where the whole document is what the editor is looking at, and
 * wrong for the property catalogue, where two people edit different
 * properties inside one document - that uses saveDocumentIfUnchanged above.
 */
export async function saveDocument<T>(
  path: string,
  content: T
): Promise<SupabaseResult<null>> {
  if (!allowed(path)) {
    return {
      ok: false,
      error: {
        status: 400,
        message: "That is not somewhere this site is allowed to save.",
      },
    };
  }

  const result = await supabaseRequest<unknown>(TABLE, {
    method: "POST",
    headers: {
      Prefer: "resolution=merge-duplicates,return=minimal",
    },
    body: [{ path, content }],
  });

  if (!result.ok) return result;
  return { ok: true, data: null };
}
